import React, { useState, useCallback, useEffect, useRef } from 'react';
import * as THREE from 'three';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
import type { Tape } from '../tapes/types';
import { stampTitle } from '../tapes/TapeBody';

interface Track {
  videoId: string;
  title: string;
  author: string;
  duration: number;
  durationText: string;
}

interface CreatorProps {
  onBack: () => void;
  onPlay: (tape: { name: string; description: string; tracks: Track[] }) => void;
  onGenerated?: () => void;
  initialKeywords?: string;
}

const TEX_BASE = '/assets/cassette/';
const TAPE_W = 14;
const TAPE_H = 0.7;
const TAPE_D = 9;

// ── 3D Cassette rendered with plain Three.js ──────────────────────────────────
function MixtapeTape3D({ name }: { name: string }) {
  const mountRef = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<{
    renderer: THREE.WebGLRenderer;
    scene: THREE.Scene;
    camera: THREE.PerspectiveCamera;
    animId: number;
    tape: THREE.Group;
  } | null>(null);

  useEffect(() => {
    const el = mountRef.current;
    if (!el) return;

    // ── Renderer ──────────────────────────────────────────────────────────────
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(el.clientWidth, el.clientHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFShadowMap;
    el.appendChild(renderer.domElement);

    // ── Scene ─────────────────────────────────────────────────────────────────
    const scene = new THREE.Scene();
    scene.background = null; // transparent

    // ── Camera ────────────────────────────────────────────────────────────────
    const camera = new THREE.PerspectiveCamera(45, el.clientWidth / el.clientHeight, 0.1, 1000);
    camera.position.set(0, 16, 18);
    camera.lookAt(0, 0, 0);

    // ── Lighting ──────────────────────────────────────────────────────────────
    const ambient = new THREE.AmbientLight(0xffffff, 0.7);
    scene.add(ambient);
    const dirLight = new THREE.DirectionalLight(0xffeedd, 1.2);
    dirLight.position.set(8, 14, 10);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    scene.add(dirLight);
    const fillLight = new THREE.DirectionalLight(0x8899cc, 0.4);
    fillLight.position.set(-6, 4, -8);
    scene.add(fillLight);

    // ── Simple table surface ──────────────────────────────────────────────────
    const tableGeo = new THREE.PlaneGeometry(80, 80);
    const tableMat = new THREE.MeshStandardMaterial({ color: 0x1a0f08, roughness: 0.9, metalness: 0.0 });
    const table = new THREE.Mesh(tableGeo, tableMat);
    table.rotation.x = -Math.PI / 2;
    table.position.y = -TAPE_H / 2 - 0.01;
    table.receiveShadow = true;
    scene.add(table);

    // ── Load FBX + textures ───────────────────────────────────────────────────
    let disposed = false;
    let animId = 0;

    (async () => {
      // Load base texture for stamping
      const texLoader = new THREE.TextureLoader();
      const baseTex = await new Promise<THREE.Texture>((resolve, reject) => {
        texLoader.load(`${TEX_BASE}audio_cassette_a_base.png`, resolve, undefined, reject);
      });

      const mixtapeTape: Tape = {
        id: '__jeem_mixtape__',
        videoId: '',
        isPlaylist: false,
        isInfinite: true,
        title: name || 'Mixtape',
        author: 'mixtape',
        tapeStyle: 0,
        textureVariant: 'a',
        progress: 0,
        timestamp: Date.now(),
        x: 0, y: 0, angle: 0,
        infiniteHistory: [],
        infiniteIndex: 0,
        infiniteConfig: {} as any,
      };

      const stampedTex = stampTitle(baseTex, name || 'Mixtape', 'a', mixtapeTape);

      // Load FBX
      const fbxLoader = new FBXLoader();
      const fbx = await new Promise<THREE.Group>((resolve, reject) => {
        fbxLoader.load(`${TEX_BASE}audio_cassettes.fbx`, resolve, undefined, reject);
      });

      if (disposed) return;

      // Find body mesh and apply stamped texture
      const bodyMesh = fbx.getObjectByName('Cube') as THREE.Mesh | null;
      if (bodyMesh) {
        bodyMesh.material = new THREE.MeshStandardMaterial({
            map: stampedTex,
          roughness: 0.5,
            metalness: 0.1,
          });
        bodyMesh.castShadow = true;
          bodyMesh.receiveShadow = true;
        }

      // Position tape
      const tape = fbx;
      tape.position.set(0, TAPE_H / 2, 0);
      scene.add(tape);

      // ── Animate ─────────────────────────────────────────────────────────────
      const clock = new THREE.Clock();
      function animate() {
        if (disposed) return;
        animId = requestAnimationFrame(animate);
        const t = clock.getElapsedTime();
        // Slow gentle rotation so user sees the 3D shape
        tape.rotation.y = Math.sin(t * 0.3) * 0.15;
        renderer.render(scene, camera);
      }
      animate();

      sceneRef.current = { renderer, scene, camera, animId: 0, tape };
    })();

    // ── Resize observer ───────────────────────────────────────────────────────
    const ro = new ResizeObserver(() => {
      if (!el) return;
      camera.aspect = el.clientWidth / el.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(el.clientWidth, el.clientHeight);
    });
    ro.observe(el);

    return () => {
      disposed = true;
      ro.disconnect();
      if (sceneRef.current) {
        cancelAnimationFrame(sceneRef.current.animId);
        sceneRef.current.renderer.dispose();
        el.removeChild(sceneRef.current.renderer.domElement);
        sceneRef.current = null;
      } else {
        cancelAnimationFrame(animId);
        renderer.dispose();
        if (renderer.domElement.parentNode === el) el.removeChild(renderer.domElement);
      }
    };
  }, [name]);

  return <div ref={mountRef} style={{ width: '100%', height: '100%' }} />;
}

// ── Fake mixtape tape for step 1 label ───────────────────────────────────────
function makeMixtapeTape(name: string, tracks: Track[]): Tape {
  return {
    id: '__jeem_mixtape__',
    videoId: tracks[0]?.videoId || '',
    isPlaylist: false,
    isInfinite: true,
    title: name || 'Mixtape',
    author: 'mixtape',
    tapeStyle: 0,
    textureVariant: 'a',
    progress: 0,
    timestamp: Date.now(),
    x: 0, y: 0, angle: 0,
    infiniteHistory: tracks.map(t => ({ videoId: t.videoId, title: t.title, author: t.author })),
    infiniteIndex: 0,
    infiniteConfig: { source: 'youtube', type: 'artist', value: name } as any,
  };
}

export function MixtapeCreator({ onBack, onPlay, onGenerated, initialKeywords }: CreatorProps) {
  const [url, setUrl] = useState('');
  const [keywords, setKeywords] = useState(initialKeywords || '');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [name, setName] = useState('');
  const [editingName, setEditingName] = useState(false);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [seedTitle, setSeedTitle] = useState('');
  const autoGenerated = useRef(false);

  const doGenerate = useCallback(async (genUrl: string, genKeywords: string) => {
    if (!genUrl.trim() && !genKeywords.trim()) {
      setError('Enter a YouTube URL or some keywords');
      return;
    }
    setLoading(true);
    setError('');
    try {
      const res = await fetch('/api/mixtape/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: genUrl.trim(), keywords: genKeywords.trim() }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Generation failed');
      setTracks(data.tracks || []);
      setSeedTitle(data.seedTitle || 'Mixtape');
      if (onGenerated) onGenerated();
    } catch (e: any) {
      setError(e.message || 'Failed to generate mixtape');
    } finally {
      setLoading(false);
    }
  }, [onGenerated]);

  const handleGenerate = useCallback(() => {
    doGenerate(url, keywords);
  }, [url, keywords, doGenerate]);

  // Auto-generate on mount if initialKeywords provided
  useEffect(() => {
    if (initialKeywords && initialKeywords.trim() && !autoGenerated.current) {
      autoGenerated.current = true;
      doGenerate('', initialKeywords);
    }
  }, [initialKeywords, doGenerate]);

  const canSave = name.trim().length > 0;

  const handleSave = useCallback(() => {
    if (!name.trim()) return;
    const tape = { name: name.trim(), description: '', tracks };
    onPlay(tape);
  }, [name, tracks, onPlay]);

  const handleRegenerate = useCallback(() => {
    setTracks([]);
    setName('');
    setError('');
  }, []);

  const mixtapeTape = makeMixtapeTape(name || seedTitle || 'Mixtape', tracks);

  return (
    <div style={styles.overlay}>
      {/* ── Step 1: URL / Keywords input (or just "Generating..." when auto-generating) ── */}
      {!tracks.length && (
        loading && initialKeywords ? (
          <div style={styles.inputModal}>
            <p style={{ ...styles.modalSubtitle, color: 'rgba(250,249,246,0.7)' }}>Generating...</p>
            {error && <p style={styles.error}>{error}</p>}
          </div>
        ) : (
          <div style={styles.inputModal}>
            <p style={styles.modalSubtitle}>Enter a YouTube URL or keywords to generate a 16-track mixtape</p>
            <div style={styles.inputGroup}>
              <input
                style={styles.input}
                type="text"
                placeholder="YouTube URL"
                value={url}
                onChange={e => setUrl(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleGenerate()}
                disabled={loading}
              />
              <span style={styles.or}>or</span>
              <input
                style={styles.input}
                type="text"
                placeholder="Keywords (e.g. 80s synthwave)"
                value={keywords}
                onChange={e => setKeywords(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleGenerate()}
                disabled={loading}
              />
            </div>
            {error && <p style={styles.error}>{error}</p>}
            <button
              className="tape-ui-btn"
              style={{ ...styles.generateBtn, ...(loading ? styles.generateBtnDisabled : {}) }}
              onClick={handleGenerate}
              disabled={loading}
            >
              {loading ? 'Generating...' : 'Generate Mixtape'}
            </button>
          </div>
        )
      )}

      {/* ── Step 2: tracklist (tape is visible on table behind) ── */}
      {tracks.length > 0 && (
        <div style={styles.creator}>
          <div style={styles.trackSide}>
            {/* Name input + save button inline */}
            <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 12 }}>
              {editingName ? (
                <input
                  style={{ ...styles.nameInput, marginBottom: 0, flex: 1 }}
                  type="text"
                  autoFocus
                  placeholder="Mixtape name..."
                  value={name}
                  onChange={e => setName(e.target.value)}
                  onKeyDown={e => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      setEditingName(false);
                    } else if (e.key === 'Escape') {
                      setEditingName(false);
                    }
                  }}
                  onBlur={() => setEditingName(false)}
                  maxLength={60}
                />
              ) : (
                <div
                  className="tape-inspect-title-display"
                  onClick={() => setEditingName(true)}
                  title="Click to edit"
                  style={{ flex: 1, width: 'auto', fontSize: '1em', textAlign: 'left', justifyContent: 'flex-start' }}
                >
                  <span className="tape-inspect-title-text">{name || 'Mixtape name...'}</span>
                  <i className="fas fa-pen tape-inspect-title-pen" aria-hidden="true" />
                </div>
              )}
              <button
                className="tape-ui-btn"
                style={{ ...styles.saveBtn, ...((loading || !canSave) ? styles.saveBtnDisabled : {}), flexShrink: 0 }}
                onClick={handleSave}
                disabled={loading || !canSave}
              >
                Save
              </button>
            </div>

            {/* Track count */}
            <p style={styles.trackCount}>{tracks.length} tracks — generated from "{seedTitle}"</p>

            {/* Track list — show all 16 */}
            <div style={styles.trackList}>
              {tracks.map((track, i) => (
                <div key={i} style={styles.trackRow}>
                  <span style={styles.trackNum}>{String(i + 1).padStart(2, '0')}.</span>
                  <span style={styles.trackTitle}>{track.title || 'Untitled'}</span>
                  <span style={styles.trackAuthor}>{track.author}</span>
                  <span style={styles.trackDuration}>{track.durationText || ''}</span>
                </div>
              ))}
            </div>

            {error && <p style={styles.error}>{error}</p>}
          </div>
        </div>
      )}
    </div>
  );
}

